import {createSimulationRegistry} from './src/simulation_contracts.js';
import {exchangeDefinitions} from './src/exchange_content.js';
import {nestedDefinitions} from './src/feature_expansion_nested_content.js';
import {nestedChainDefinitions} from './src/feature_expansion_nested_chains.js';
import {remainderConsequencesDefinitions} from './src/audit_remainder_consequences_content.js';
const families=['people','commands','powers','advancements','sites','events','controllers','transitions','origins','conditions','encounters','energies','pursuits','situations'];
const sources=[exchangeDefinitions,nestedDefinitions,nestedChainDefinitions,remainderConsequencesDefinitions];
const merged=Object.fromEntries(families.map(k=>[k,sources.flatMap(d=>d[k]||[])]));
const registry=createSimulationRegistry(merged);
console.log(JSON.stringify({commands:registry.commands.size,controllers:registry.controllers.size,situations:registry.situations.size,events:registry.events.size}));
